# Autogenerated strategy: MACD crossover entries with ATR-based trailing stops
# Exports: compute_indicators, order_func

from typing import Any, Dict, Tuple
import numpy as np
import pandas as pd

# Persistent state for order function keyed by context id
_ORDER_STATE: Dict[int, Dict[str, Any]] = {}


def compute_indicators(
    ohlcv: pd.DataFrame,
    macd_fast: int = 12,
    macd_slow: int = 26,
    macd_signal: int = 9,
    sma_period: int = 50,
    atr_period: int = 14,
) -> Dict[str, np.ndarray]:
    """Compute indicators required by the strategy.

    Returns a dict containing numpy arrays for keys:
    'close', 'high', 'macd', 'signal', 'atr', 'sma'. Arrays align with input index.

    The implementation uses only past data (no lookahead) and is deterministic.
    """
    # Basic validation
    if not isinstance(ohlcv, pd.DataFrame):
        raise TypeError("ohlcv must be a pandas DataFrame with columns: high, low, close")

    required_cols = {"high", "low", "close"}
    if not required_cols.issubset(set(ohlcv.columns)):
        raise ValueError(f"ohlcv must contain columns: {required_cols}")

    # Work on copies and ensure float dtype
    high = ohlcv["high"].astype(float).copy()
    low = ohlcv["low"].astype(float).copy()
    close = ohlcv["close"].astype(float).copy()

    # MACD: difference of EMAs (fast - slow) and signal line as EMA of MACD
    # Use pandas ewm with adjust=False for causal EMA
    fast_ema = close.ewm(span=macd_fast, adjust=False).mean()
    slow_ema = close.ewm(span=macd_slow, adjust=False).mean()
    macd = fast_ema - slow_ema
    signal = macd.ewm(span=macd_signal, adjust=False).mean()

    # ATR: True Range then Wilder's smoothing via ewm with alpha=1/atr_period
    prev_close = close.shift(1)
    tr1 = high - low
    tr2 = (high - prev_close).abs()
    tr3 = (low - prev_close).abs()
    tr = pd.concat([tr1, tr2, tr3], axis=1).max(axis=1)
    # For the very first row, prev_close is NaN; set tr to high-low there
    if len(tr) > 0:
        if np.isnan(tr.iloc[0]):
            tr.iloc[0] = (high.iloc[0] - low.iloc[0])
    # Wilder smoothing
    atr = tr.ewm(alpha=1.0 / float(max(1, atr_period)), adjust=False).mean()

    # SMA trend filter. Use min_periods=sma_period to produce NaN for warmup.
    sma = close.rolling(window=sma_period, min_periods=sma_period).mean()

    # Return numpy arrays for downstream consumption
    return {
        "close": close.values,
        "high": high.values,
        "macd": macd.values,
        "signal": signal.values,
        "atr": atr.values,
        "sma": sma.values,
    }


def order_func(
    c: Any,
    close: np.ndarray,
    high: np.ndarray,
    macd: np.ndarray,
    signal: np.ndarray,
    atr: np.ndarray,
    sma: np.ndarray,
    trailing_mult: float,
) -> Tuple[float, int, int]:
    """Order function for vectorbt.Portfolio.from_order_func (use_numba=False).

    Returns a tuple (size, size_type, direction) where:
    - size: positive for buy, negative for sell; np.nan for no order
    - size_type and direction are integer codes expected by vectorbt's order_nb

    Logic implemented:
    - Long entry when MACD crosses above signal AND close > sma
    - Exit when MACD crosses below signal OR close < (highest_since_entry - trailing_mult * atr)

    State is stored in a module-level dictionary keyed by id(c) so that we do not
    attempt to attach attributes to the context object (which may be restricted).
    """
    # Convert inputs to numpy arrays if they are pandas Series
    close = np.asarray(close)
    high = np.asarray(high)
    macd = np.asarray(macd)
    signal = np.asarray(signal)
    atr = np.asarray(atr)
    sma = np.asarray(sma)

    ctx_id = id(c)
    st = _ORDER_STATE.get(ctx_id)
    if st is None:
        st = {
            "in_long": False,
            "entry_idx": None,
            "highest_since_entry": -np.inf,
            "entry_price": np.nan,
        }
        _ORDER_STATE[ctx_id] = st

    # Current bar index
    i = int(getattr(c, "i", 0))

    # Defensive: if index out of bounds, do nothing
    if i < 0 or i >= len(close):
        return (np.nan, 0, 0)

    # Helper to check for NaN values in indicators
    def _is_valid(val: float) -> bool:
        return not (val is None or (isinstance(val, float) and np.isnan(val)))

    # Prepare current and previous values
    macd_curr = macd[i]
    sig_curr = signal[i]
    macd_prev = macd[i - 1] if i > 0 else np.nan
    sig_prev = signal[i - 1] if i > 0 else np.nan

    close_curr = close[i]
    sma_curr = sma[i] if i < len(sma) else np.nan
    atr_curr = atr[i] if i < len(atr) else np.nan

    # Detect MACD cross up/down
    cross_up = False
    cross_down = False
    if _is_valid(macd_curr) and _is_valid(sig_curr) and _is_valid(macd_prev) and _is_valid(sig_prev):
        cross_up = (macd_prev <= sig_prev) and (macd_curr > sig_curr)
        cross_down = (macd_prev >= sig_prev) and (macd_curr < sig_curr)

    # ENTRY: MACD cross up + price above SMA
    if not st["in_long"]:
        if cross_up and _is_valid(sma_curr) and _is_valid(close_curr):
            if close_curr > sma_curr:
                # Enter long: buy 1 unit (size_type=0 -> Amount, direction=1 -> Long)
                st["in_long"] = True
                st["entry_idx"] = i
                st["entry_price"] = close_curr
                st["highest_since_entry"] = high[i] if _is_valid(high[i]) else close_curr
                return (1.0, 0, 1)
        return (np.nan, 0, 0)

    # IN-POSITION: update highest high since entry
    if st["in_long"]:
        if _is_valid(high[i]) and high[i] > st["highest_since_entry"]:
            st["highest_since_entry"] = high[i]

        # Compute trailing stop if ATR is valid
        trailing_triggered = False
        if _is_valid(atr_curr) and np.isfinite(st["highest_since_entry"]):
            trailing_stop = st["highest_since_entry"] - float(trailing_mult) * float(atr_curr)
            if _is_valid(close_curr) and close_curr < trailing_stop:
                trailing_triggered = True

        # EXIT: MACD bearish cross OR trailing stop triggered
        if cross_down or trailing_triggered:
            # Close the long position: sell 1 unit
            st["in_long"] = False
            st["entry_idx"] = None
            st["entry_price"] = np.nan
            st["highest_since_entry"] = -np.inf
            return (-1.0, 0, 1)

    # Default: no action
    return (np.nan, 0, 0)
